# Manual closed frame detection - check all possible rectangles

def find_closed_rectangles(grid):
    """Find all closed rectangular frames in the grid"""
    rows = len(grid)
    cols = len(grid[0])

    frames = []

    # Check each possible rectangle size
    for height in range(2, rows + 1):
        for width in range(2, cols + 1):
            for start_r in range(rows - height + 1):
                for start_c in range(cols - width + 1):
                    end_r = start_r + height - 1
                    end_c = start_c + width - 1

                    # Get corner colors to determine frame color
                    top_left = grid[start_r][start_c]
                    top_right = grid[start_r][end_c]
                    bot_left = grid[end_r][start_c]
                    bot_right = grid[end_r][end_c]

                    # Check if all corners have the same color (potential frame)
                    if top_left != top_right or top_left != bot_left or top_left != bot_right:
                        continue

                    frame_color = top_left

                    # Skip background color
                    if frame_color == 4:
                        continue

                    # Check if all 4 sides are the frame color
                    is_frame = True

                    # Top side
                    for c in range(start_c, end_c + 1):
                        if grid[start_r][c] != frame_color:
                            is_frame = False
                            break
                    if not is_frame:
                        continue

                    # Bottom side
                    for c in range(start_c, end_c + 1):
                        if grid[end_r][c] != frame_color:
                            is_frame = False
                            break
                    if not is_frame:
                        continue

                    # Left side
                    for r in range(start_r, end_r + 1):
                        if grid[r][start_c] != frame_color:
                            is_frame = False
                            break
                    if not is_frame:
                        continue

                    # Right side
                    for r in range(start_r, end_r + 1):
                        if grid[r][end_c] != frame_color:
                            is_frame = False
                            break
                    if not is_frame:
                        continue

                    # This is a closed frame!
                    frames.append({
                        'color': frame_color,
                        'rows': (start_r, end_r),
                        'cols': (start_c, end_c),
                        'interior_rows': end_r - start_r - 1,
                        'interior_cols': end_c - start_c - 1
                    })

    return frames

